/****** Object:  UserDefinedFunction [dbo].[FN_AggLinkID]    Script Date: 2025/12/31 下午 01:32:25 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_AggLinkID](@classMaster nvarchar(50), @orderNo nvarchar(50), @productNo nvarchar(50), @serialNo nvarchar(100))
RETURNS nvarchar(MAX) AS 
BEGIN
	DECLARE @tmpString nvarchar(MAX) ;
	SET @tmpString = '' ;
		
	SELECT @tmpString = @tmpString + LinkID + ','
	FROM dbo.SFC_StationIDLink
	WHERE StationNO = @classMaster AND OrderNO = @orderNo AND PartNO = @productNo AND SerialNO = @serialNo
	ORDER BY LinkID ASC

	RETURN SUBSTRING(@tmpString, 1, len(@tmpString)-1)
END
GO
/****** Object:  UserDefinedFunction [dbo].[FN_SplitString]    Script Date: 2025/12/31 下午 01:32:25 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_SplitString]
(
	@string nvarchar(max),
	@delimiter nchar(1)
)
RETURNS @tParts TABLE ( result nvarchar(2048) )
AS
BEGIN
	DECLARE @countOfDelimiter int
	DECLARE @startPos int
	DECLARE @endPos int
	DECLARE @segmentLen int
	DECLARE @segmentStr nvarchar(MAX)
	DECLARE @countOfRun int

	SET @startPos = 0
	SET @countOfRun = 0
	SET @delimiter = ','
	SET @countOfDelimiter = LEN(@string) - LEN(REPLACE(@string, ',', ''))
	
	IF @countOfDelimiter = 0
	BEGIN
		INSERT INTO @tParts VALUES(@string)
		RETURN
	END

	WHILE @countOfRun != @countOfDelimiter+1
	BEGIN
		SET @countOfRun = @countOfRun + 1
		SET @endPos = CHARINDEX(@delimiter, @string, @startPos)

		IF @endPos = 0
			BEGIN
				SET @segmentStr = SUBSTRING(@string, @startPos, LEN(@string))
				INSERT INTO @tParts VALUES(@segmentStr)
			END
		ELSE
			BEGIN
				SET @segmentLen = @endPos - @startPos	
				SET @segmentStr = SUBSTRING(@string, @startPos, @segmentLen)
				INSERT INTO @tParts VALUES(@segmentStr)
				SET @startPos = @endPos + 1
			END
	END
	RETURN 
END
GO
