/****** Object:  View [dbo].[IndicatorAnomalyLog]    Script Date: 2025/12/31 下午 01:32:25 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[IndicatorAnomalyLog]
AS
SELECT          B.LogDateTime, B.OrderNO, B.StationNO, B.Name, B.IndicatorNO, B.IndicatorStatus, B.Value
FROM              (SELECT          MAX(LogDateTime) AS LogDateTime, OrderNO, StationNO, IndicatorNO
                            FROM               dbo.SFC_IndicatorAnomalyLog
                            GROUP BY    OrderNO, StationNO, IndicatorNO) AS A LEFT OUTER JOIN
                                (SELECT          LogDateTime, OrderNO, StationNO, Name, IndicatorNO, IndicatorStatus, Value
                                  FROM               dbo.SFC_IndicatorAnomalyLog AS SFC_IndicatorAnomalyLog_1) AS B ON 
                            A.LogDateTime = B.LogDateTime AND A.OrderNO = B.OrderNO AND A.StationNO = B.StationNO AND 
                            A.IndicatorNO = B.IndicatorNO
