CREATE PROCEDURE [dbo].[WorkOrderSettlementUpdate]
     @wo nvarchar(50),
     @StationNO nvarchar(50),
	 @indexSN int,
	 @serverId nvarchar(50)
AS
BEGIN
     -- Local Variables
     DECLARE @quantity int
     DECLARE @tmpStationFPY float
     DECLARE @maxAvrageCycleTime float
     DECLARE @maxTotalOutput int
     DECLARE @maxCumlativeTime int

     -- Result Variables for SFC_WorkOrder_Settlement
     DECLARE @total_CI int
     DECLARE @total_CO int

     DECLARE @total_I int
     DECLARE @total_O int
     DECLARE @total_F int
     DECLARE @total_K int

     DECLARE @fpy float
     DECLARE @yieldRate float
     DECLARE @stationYieldRate float

	 DECLARE @avgWT float
     DECLARE @avgCT float
     
     -- UPDATE SFC_WorkOrder_Settlement

	 -- SN I & O
     SET @total_CI = (SELECT COUNT(*) FROM SoftNetLogDB.dbo.SFC_StationDetail WHERE ServerId = @serverId AND OrderNO = @wo AND StationNO = @StationNO AND IndexSN = @indexSN AND IsCheckedInFlag = '1')
     SET @total_CO = (SELECT COUNT(*) FROM SoftNetLogDB.dbo.SFC_StationDetail WHERE ServerId = @serverId AND OrderNO = @wo AND StationNO = @StationNO AND IndexSN = @indexSN AND IsCheckedOutFlag = '1')

     -- By WO & Station Qty
     SET @total_I = (SELECT IIF((SELECT Top 1 IsCheckedInFlag FROM SoftNetLogDB.dbo.SFC_StationDetail 
                       WHERE ServerId = @serverId AND OrderNO = @wo AND StationNO = @StationNO AND IndexSN = @indexSN )='1',
                       Count(1),(SUM(ProductFinishedQty)+SUM(ProductFailedQty)))
                       FROM SoftNetLogDB.dbo.SFC_StationDetail WHERE ServerId = @serverId AND OrderNO = @wo AND StationNO = @StationNO AND IndexSN = @indexSN)
     SET @total_O = (SELECT SUM(ProductFinishedQty) 
					FROM SoftNetLogDB.dbo.SFC_StationDetail WHERE ServerId = @serverId AND OrderNO = @wo AND StationNO = @StationNO AND IndexSN = @indexSN)
     SET @total_F = (SELECT SUM(ProductFailedQty) 
					FROM SoftNetLogDB.dbo.SFC_StationDetail WHERE ServerId = @serverId AND OrderNO = @wo AND StationNO = @StationNO AND IndexSN = @indexSN)
     SET @total_K = (SELECT COUNT(*) 
					FROM SoftNetLogDB.dbo.SFC_StationDetail WHERE ServerId = @serverId AND OrderNO = @wo AND StationNO = @StationNO AND IndexSN = @indexSN AND KeepFlag = 1)
     SET @total_I =IIF(@total_I IS NULL,0,@total_I)
	 SET @total_O =IIF(@total_O IS NULL,0,@total_O)
	 SET @total_F =IIF(@total_F IS NULL,0,@total_F)
	 SET @total_K =IIF(@total_K IS NULL,0,@total_K)

     -- Yield Rate
     SET @fpy = IIF(@total_I=0,0,(@total_O - @total_K) * 1.0 / @total_I)
     SET @yieldRate = IIF(@total_I=0,0,@total_O  * 1.0 / @total_I)
     SET @stationYieldRate = IIF((@total_I + @total_K) = 0,0, @total_O * 1.0 / (@total_I + @total_K))

	 SET @avgCT = (SELECT 
					IIF(SUM(B.InQty)=0,0,SUM(B.CT)/SUM(B.InQty)) 
					FROM 
					(
						SELECT CycleTime*(SUM(ProductFinishedQty)+SUM(ProductFailedQty)) 'CT',
						SUM(ProductFinishedQty)+SUM(ProductFailedQty) 'InQty'
						FROM SoftNetLogDB.dbo.SFC_StationDetail 
						WHERE ServerId = @serverId AND IsDel=0 AND CycleTime!=0 and OrderNO = @wo AND StationNO = @StationNO AND IndexSN = @indexSN
						GROUP BY OrderNO,StationNO,CycleTime
					) B)
	 SET @avgWT = (SELECT 
					IIF(SUM(B.InQty)=0,0,SUM(B.WT)/SUM(B.InQty)) 
					FROM 
					(
						SELECT WaitTime*(SUM(ProductFinishedQty)+SUM(ProductFailedQty)) 'WT',
						SUM(ProductFinishedQty)+SUM(ProductFailedQty) 'InQty'
						FROM SoftNetLogDB.dbo.SFC_StationDetail 
						WHERE ServerId = @serverId AND IsDel=0 AND WaitTime!=0 and OrderNO = @wo AND StationNO = @StationNO AND IndexSN = @indexSN
						GROUP BY OrderNO,StationNO,WaitTime
					) B)

     SELECT 
         @wo AS _OrderNo,
         @StationNO AS _SataionNo,

         @total_CI AS _TotalCheckIn,
         @total_CO AS _TotalCheckOut,

         @total_I AS _TotalInput,
         @total_O AS _TotalOutput,
         @total_F AS _TotalFail,
         @total_K AS _TotalKeep,

         @fpy AS _FPY,
         @yieldRate AS _YieldRate,
         @stationYieldRate AS _StationYieldRate,
		 @avgWT AS _AVGWT,
         @avgCT AS _AVGCT
     RETURN
END
